import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        if (!dictionary.contains(endWord)) return 0;
        List<String> words = new ArrayList<>(dictionary);
        if (!dictionary.contains(beginWord)) words.add(beginWord);
        int start = words.indexOf(beginWord), target = words.indexOf(endWord);
        List<List<Integer>> graph = new ArrayList<>();
        for (int index = 0; index < words.size(); index++) graph.add(new ArrayList<>());
        for (int first = 0; first < words.size(); first++) for (int second = first + 1; second < words.size(); second++) {
            if (oneLetterApart(words.get(first), words.get(second))) { graph.get(first).add(second); graph.get(second).add(first); }
        }
        int[] distance = new int[words.size()]; Arrays.fill(distance, -1);
        Queue<Integer> queue = new ArrayDeque<>(); distance[start] = 1; queue.offer(start);
        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current == target) return distance[current];
            for (int next : graph.get(current)) if (distance[next] == -1) { distance[next] = distance[current] + 1; queue.offer(next); }
        }
        return 0;
    }
    private boolean oneLetterApart(String first, String second) {
        int differences = 0;
        for (int index = 0; index < first.length(); index++) if (first.charAt(index) != second.charAt(index) && ++differences > 1) return false;
        return differences == 1;
    }
}

