import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        if (!dictionary.contains(endWord)) return 0;
        int length = beginWord.length();
        Map<String, List<String>> buckets = new HashMap<>();
        for (String word : dictionary) for (int index = 0; index < length; index++) {
            String pattern = word.substring(0, index) + '*' + word.substring(index + 1);
            buckets.computeIfAbsent(pattern, key -> new ArrayList<>()).add(word);
        }
        Queue<String> queue = new ArrayDeque<>();
        Map<String, Integer> distance = new HashMap<>();
        queue.offer(beginWord); distance.put(beginWord, 1);
        while (!queue.isEmpty()) {
            String current = queue.poll();
            int nextDistance = distance.get(current) + 1;
            if (current.equals(endWord)) return distance.get(current);
            for (int index = 0; index < length; index++) {
                String pattern = current.substring(0, index) + '*' + current.substring(index + 1);
                for (String next : buckets.getOrDefault(pattern, List.of())) {
                    if (!distance.containsKey(next)) { distance.put(next, nextDistance); queue.offer(next); }
                }
                buckets.remove(pattern);
            }
        }
        return 0;
    }
}
